import{_ as n,C as t,o,c as i,E as a,a2 as c}from"./chunks/framework.VWKgVqrc.js";const d="/joinwell52/assets/eval-evidence-20261114/eval-boundary.en.svg",w=JSON.parse('{"title":"When AI checks AI, who checks the evidence it saw?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"When AI checks AI, who checks the evidence it saw?","date":"2026-11-14","published_date":"2026-11-14","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"What evidence must a second AI see before its favorable review can support delivery?","summary":"A report has the right number of items, the current evidence version, and valid authorization, yet says B-23 where the task asked for B-22. Seven controlled cases show what rules and two models can catch, and what they cannot establish.","cover":"/assets/eval-evidence-20261114/eval-evidence.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Seven controlled cases, label-blinded judgments by two real models, CodeFlowMu source and targeted tests; no product EVAL end-to-end acceptance test","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-14-eval-needs-evidence.md","filePath":"en/research/2026-11-14-eval-needs-evidence.md","lastUpdated":null}'),h={name:"en/research/2026-11-14-eval-needs-evidence.md"};function l(u,e,p,m,v,g){const r=t("ArticleCover"),s=t("ArticleTableScroll");return o(),i("div",null,[a(r,{image:"/assets/eval-evidence-20261114/eval-evidence.cover-v1.png",kicker:"Engineering research · Independent acceptance",title:"When AI checks AI, who checks the evidence it saw?",summary:"A report has the right number of items, the current evidence version, and valid authorization, yet says B-23 where the task asked for B-22. Seven controlled cases show what rules and two models can catch, and what they cannot establish.",version:"2026-11-14",languageHref:"/zh/research/2026-11-14-eval-needs-evidence",languageLabel:"中文"}),a(s,{language:"en"}),e[0]||(e[0]=c('<h1 id="when-ai-checks-ai-who-checks-the-evidence-it-saw" tabindex="-1">When AI checks AI, who checks the evidence it saw? <a class="header-anchor" href="#when-ai-checks-ai-who-checks-the-evidence-it-saw" aria-label="Permalink to &quot;When AI checks AI, who checks the evidence it saw?&quot;">​</a></h1><p>You ask an AI worker to place an order and deliver a report listing two products. It says the job is done. There is exactly one order, two report items, a current evidence version, and publication authorization. The programmatic checks pass. Yet you requested <strong>B-22</strong>, and the report says <strong>B-23</strong>. Who catches that one-character difference?</p><p>“Ask another AI to review it” is a natural answer. A <a href="https://github.com/browser-use/browser-use/pull/6398" target="_blank" rel="noreferrer">browser-use change</a> adds a same-model judgment after a run and records the judgment&#39;s usage and cost separately. That creates a useful observation. It also raises a harder question: <strong>does the reviewer see the original request and actual result, or only the executor&#39;s account of success?</strong></p><p>We are building CodeFlowMu, a local multi-agent collaboration system. It separates worker reports, formal task state, and independent evaluation. We ran a small, controlled acceptance experiment to examine what that separation buys and what it still depends on.</p><h2 id="the-count-is-right-the-content-is-wrong" tabindex="-1">The count is right; the content is wrong <a class="header-anchor" href="#the-count-is-right-the-content-is-wrong" aria-label="Permalink to &quot;The count is right; the content is wrong&quot;">​</a></h2><p>We fixed the labels for seven business-task cases before evaluation: one acceptable delivery and six failures. The failures were a missing item, evidence for an old artifact version, unauthorized publication, a duplicate order, no order at all, and B-23 substituted for B-22. Every worker report claimed success. These were authored facts, not real orders, users, or formal CodeFlowMu EVAL requests. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-14-eval-needs-evidence/00-report.en.md" target="_blank" rel="noreferrer">public evidence package</a> contains the method, prompts, and per-case outcomes.</p><p>First we checked order count, delivered item count, evidence version, and authorization with code. It rejected five of the six bad deliveries but accepted one: <strong>B-23</strong> still satisfies the rule “two items.” A scripted negative control that simply believed the worker&#39;s success report accepted all six bad deliveries. That control was not a model self-review.</p><table tabindex="0"><thead><tr><th>Review method</th><th style="text-align:right;">False accepts in these seven cases</th><th>Available evidence</th></tr></thead><tbody><tr><td>Script that trusts the success report</td><td style="text-align:right;">6</td><td>The worker&#39;s claim</td></tr><tr><td>Rules for count, version, and authorization</td><td style="text-align:right;">1</td><td>Enumerable business facts, without semantic SKU comparison</td></tr><tr><td>Two models given the request and current facts</td><td style="text-align:right;">0 each</td><td>Exact product content plus those facts</td></tr></tbody></table><p>We gave the same cases to two models in separate sessions, withholding the fixed acceptance labels. <code>gpt-6.1-sol</code> and <code>gpt-6-astra</code> each accepted one and rejected six; both identified the B-23/B-22 mismatch. We then let the rules filter first and sent only the two remaining cases to a model. It accepted the correct artifact and rejected the wrong product. That combination worked <strong>in this simple fixture</strong>. Seven cases cannot establish a production miss rate, and a different model name does not prove independent judgment.</p><figure><img src="'+d+'" alt="A worker&#39;s success report is compared with the original request, business record, current artifact, and authorization. Rules reject five error types; semantic review catches the SKU mismatch. Model output remains an observation before formal acceptance."><figcaption>The division of work in this controlled experiment: rules check enumerable facts; a model compares content the rules did not cover. Both depend on trustworthy inputs.</figcaption></figure><h2 id="why-did-the-models-get-it-right" tabindex="-1">Why did the models get it right? <a class="header-anchor" href="#why-did-the-models-get-it-right" aria-label="Permalink to &quot;Why did the models get it right?&quot;">​</a></h2><p>The key condition is easy to miss. The prompts <strong>directly supplied</strong> “requested B-22, delivered B-23,” along with the order count, evidence version, and authorization fact. The models correctly compared information they were shown. The experiment did <strong>not</strong> establish that a real execution system can deliver current, trustworthy facts to an evaluator.</p><p>Replace those inputs with “the worker says completed; see report.” Even ten models cannot infer whether the business system holds an order from that sentence. A screenshot of an older artifact may likewise look like current work. Before accepting a delivery, the reviewer needs traceable access to four sources: <strong>the original request, the current artifact version, the external business record, and authorization</strong>. If a source is missing, its corresponding conclusion remains unverified.</p><p>CodeFlowMu&#39;s current source also separates an evaluation observation from formal permission. It persists an independent EVAL request before launching a model; if the receipt is lost, the same request remains unknown instead of automatically making another paid call. The observation carries <code>grants_authority=false</code> and does not itself change formal task state. Targeted transport tests passed. A broader evaluation contract test in this run stopped at its administrator-token prerequisite before reaching its assertions. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-14-eval-needs-evidence/00-report.en.md" target="_blank" rel="noreferrer">evidence package</a> records both scopes. This is neither a confirmed product defect nor an end-to-end product acceptance pass.</p><h2 id="looks-good-is-not-an-acceptance-authority" tabindex="-1">“Looks good” is not an acceptance authority <a class="header-anchor" href="#looks-good-is-not-an-acceptance-authority" aria-label="Permalink to &quot;“Looks good” is not an acceptance authority&quot;">​</a></h2><p>Our engineering judgment is to <strong>bind the evidence, compare the result, and leave settlement to an authorized party</strong>. Code can verify order counts, artifact versions, and authorization records. A model can help compare the task language with artifact content. When the external result cannot be read, both should preserve uncertainty. A post-run judgment is useful, but it is one observation toward acceptance.</p><p>The next test must connect these cases to real tasks and artifacts. What can the executor and evaluator each read? Can a late report replace the artifact under review? When a human reviewer disagrees with the model, who may change formal state? Seven clear prompts cannot answer those questions for us.</p><p>If you rely on an AI team to deliver work, ask one question of every “pass”: <strong>was the evidence the reviewer saw really the latest result of this task?</strong></p>',18))])}const b=n(h,[["render",l]]);export{w as __pageData,b as default};
